/**
 * @file timer_manager.c
 *
 * @brief Implements the Timer Manager.
 *
 * This file contains the pool of software timers, their lifecycle handling
 * and the periodic processing that detects expiry, as defined in
 * architecture section 3.10.
 */

#include "timer_manager.h"

/* main.h is generated by STM32CubeMX and includes the HAL header of the
 * target family (stm32f3xx_hal.h on the STM32F3, stm32f0xx_hal.h on the
 * STM32F0). Including it instead of a family-specific HAL header lets this
 * file build unchanged on both devices. Only HAL_GetTick() is used. */
#include "main.h"

/*
 * Software timer state machine (architecture section 3.10.6)
 * ----------------------------------------------------------
 * Each pool slot tracks one timing request on behalf of a consumer, so that
 * the consumer can wait for an interval without blocking the main loop.
 *
 *   IDLE    --> ACTIVE    TimerManager_Start() claims a free slot
 *   ACTIVE  --> EXPIRED   TimerManager_Process() sees the interval elapse
 *   EXPIRED --> IDLE      TimerManager_Stop() releases the timer
 *   ACTIVE  --> IDLE      TimerManager_Stop() cancels before the timeout
 *
 * There is no EXPIRED --> ACTIVE edge. A consumer that needs a further
 * interval stops its timer and starts a new one, which is how periodic
 * operation is provided. Expiry is reached only in TimerManager_Process();
 * TimerManager_IsExpired() reports the state and never advances it, so a
 * consumer may poll it on every pass of the loop.
 */

/**
 * @brief Defines the lifecycle states of a software timer.
 *
 * The states are internal to the Timer Manager. No interface in section
 * 3.10.3 exposes them, so consumers observe expiry through
 * TimerManager_IsExpired() instead.
 */
typedef enum
{
    TIMER_STATE_IDLE = 0,
    TIMER_STATE_ACTIVE,
    TIMER_STATE_EXPIRED
} TimerState_t;

/**
 * @brief Holds the data of a single software timer.
 */
typedef struct
{
    uint32_t     start_tick;
    uint32_t     timeout_ms;
    TimerState_t state;
} Timer_t;

/** The software timers owned by the Timer Manager. */
static Timer_t timer_pool[SEB_CFG_TIMER_MAX_COUNT];

/** Set once TimerManager_Init() has prepared the pool. */
static bool is_initialized = false;

/**
 * Millisecond tick read at the start of TimerManager_Process().
 *
 * Reading the tick once per call is what lets every module evaluate its
 * timers against the same instant within one main loop iteration.
 */
static uint32_t tick_snapshot = 0U;

/**
 * @brief Reports whether a timer handle refers to a timer in the pool.
 *
 * SEB_TIMER_HANDLE_INVALID lies outside the pool range, so the range check
 * rejects it as well. Every public function validates a handle here before
 * it is used as an index.
 *
 * @param timer
 *        Handle to check.
 *
 * @return true when the handle can be used to index the pool.
 */
static bool TimerManager_IsHandleValid(TimerHandle_t timer)
{
    return ((uint32_t)timer < SEB_CFG_TIMER_MAX_COUNT);
}

Status_t TimerManager_Init(void)
{
    uint32_t index;

    for (index = 0U; index < SEB_CFG_TIMER_MAX_COUNT; index++)
    {
        timer_pool[index].start_tick = 0U;
        timer_pool[index].timeout_ms = 0U;
        timer_pool[index].state      = TIMER_STATE_IDLE;
    }

    tick_snapshot  = 0U;
    is_initialized = true;

    return STATUS_OK;
}

TimerHandle_t TimerManager_Start(uint32_t timeout)
{
    TimerHandle_t handle = SEB_TIMER_HANDLE_INVALID;
    uint32_t      index;

    if (is_initialized)
    {
        for (index = 0U; index < SEB_CFG_TIMER_MAX_COUNT; index++)
        {
            if (timer_pool[index].state == TIMER_STATE_IDLE)
            {
                /* The tick is read here rather than reused from tick_snapshot
                 * so that a timer started part way through a loop iteration
                 * is measured from when it was started. */
                timer_pool[index].start_tick = HAL_GetTick();
                timer_pool[index].timeout_ms = timeout;
                timer_pool[index].state      = TIMER_STATE_ACTIVE;

                /* The loop bound keeps index below SEB_CFG_TIMER_MAX_COUNT,
                 * so it always fits the narrower handle type. */
                handle = (TimerHandle_t)index;
                break;
            }
        }
    }

    return handle;
}

void TimerManager_Stop(TimerHandle_t timer)
{
    if (TimerManager_IsHandleValid(timer))
    {
        timer_pool[timer].state = TIMER_STATE_IDLE;
    }
}

bool TimerManager_IsExpired(TimerHandle_t timer)
{
    bool expired = false;

    if (TimerManager_IsHandleValid(timer))
    {
        expired = (timer_pool[timer].state == TIMER_STATE_EXPIRED);
    }

    return expired;
}

uint32_t TimerManager_GetElapsed(TimerHandle_t timer)
{
    uint32_t elapsed = 0U;

    /* The handle check is evaluated first, so the pool is never indexed with
     * an out of range handle. An idle slot holds no start reference, so it
     * reports zero rather than a meaningless age. */
    if (TimerManager_IsHandleValid(timer) &&
        (timer_pool[timer].state != TIMER_STATE_IDLE))
    {
        /* The tick is read here rather than taken from tick_snapshot: this
         * answers how long ago the timer started as of now, whether or not
         * TimerManager_Process() has run during this loop iteration. The
         * subtraction wraps for the same reason as the expiry test, so the
         * result stays correct across the rollover of the tick. */
        elapsed = HAL_GetTick() - timer_pool[timer].start_tick;
    }

    return elapsed;
}

void TimerManager_Process(void)
{
    uint32_t index;
    uint32_t elapsed;

    if (is_initialized)
    {
        tick_snapshot = HAL_GetTick();

        for (index = 0U; index < SEB_CFG_TIMER_MAX_COUNT; index++)
        {
            if (timer_pool[index].state == TIMER_STATE_ACTIVE)
            {
                /* The wraparound of this subtraction is intentional and is
                 * what makes the timer survive the rollover of the 32-bit
                 * tick. Unsigned arithmetic is defined to wrap, so the
                 * result is the true elapsed count even when the tick has
                 * passed zero since the timer started. Storing an absolute
                 * deadline instead would wrap to a small value and expire
                 * the timer immediately. */
                elapsed = tick_snapshot - timer_pool[index].start_tick;

                if (elapsed >= timer_pool[index].timeout_ms)
                {
                    timer_pool[index].state = TIMER_STATE_EXPIRED;
                }
            }
        }
    }
}
